/** 中国省级底图(预投影 SVG path)。源:阿里云 DataV GeoAtlas(areas_v3)省级行政区划,
 * 含南海九段线图层(adcode "100000_JD");由 geojson 等经纬投影烤制,锚点残差 <0.01px。 */
export type ChinaProvince = {
  name: string;
  adcode: number | string;
  paths: string[];
};

export type ChinaMapData = {
  viewBox: string;
  provinces: ChinaProvince[];
};

/** 经纬度 → viewBox 坐标(与底图生成仿射一致,锚点残差 <0.01px)。 */
export function projectChina(longitude: number, latitude: number): { x: number; y: number } {
  return {
    x: 12.800376739218803 * longitude - 934.4461662873192,
    y: -15.82166864235793 * latitude + 846.4598878701353,
  };
}

